import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 35 Justice was done","description":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 35 Justice was done","description":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 情态动词的被动结构，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 34 A happy discovery","link":"/life/english/new-concept/book-3/unit-02/lesson-034"},"next":{"text":"第三册：培养技能 · Lesson 36 A chance in a million","link":"/life/english/new-concept/book-3/unit-02/lesson-036"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 34 A happy discovery","link":"/life/english/new-concept/book-3/unit-02/lesson-034"},"next":{"text":"第三册：培养技能 · Lesson 36 A chance in a million","link":"/life/english/new-concept/book-3/unit-02/lesson-036"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-035.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-035.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-035.md"};function s(l,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-35-justice-was-done" tabindex="-1">第三册：培养技能 · Lesson 35 Justice was done <a class="header-anchor" href="#第三册-培养技能-·-lesson-35-justice-was-done" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 35 Justice was done&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕公平处理和结果说明，练习把个人感受与可陈述的处理步骤分开。学习表达应被完成的事项与已经发生的措施，避免把道德赞同等同于程序正确。通过情态动词的被动结构说明责任、可能性和要求，并保留不同情态词之间的力度差别。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>fairness</td><td>/ˈfeənəs/</td><td>n.</td><td>公平</td><td>procedural fairness</td></tr><tr><td>complaint</td><td>/kəmˈpleɪnt/</td><td>n.</td><td>投诉</td><td>review a complaint</td></tr><tr><td>decision</td><td>/dɪˈsɪʒən/</td><td>n.</td><td>决定</td><td>explain a decision</td></tr><tr><td>restore</td><td>/rɪˈstɔː/</td><td>v.</td><td>恢复</td><td>restore confidence</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take into account — 考虑相关因素</li><li>give someone a chance — 给某人机会</li></ul><h2 id="语法讲解-情态动词的被动结构" tabindex="-1">语法讲解：情态动词的被动结构 <a class="header-anchor" href="#语法讲解-情态动词的被动结构" aria-label="Permalink to &quot;语法讲解：情态动词的被动结构&quot;">​</a></h2><p>情态动词加 be 再加过去分词可表示某事应当、必须或可能被做，例如 should be reviewed。情态词后 be 保持原形，不随主语变化。must be done 强调必要性，may be done 表示许可或可能，需看上下文；must have been done 则常对过去已发生的被动动作作推断。不要把 should be done 的建议当作已经完成的事实。讨论公平处理时，可先说明标准，再报告实际步骤，避免情态要求与结果报告混写。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Both statements should be examined before a decision is announced.</p></blockquote><p>作出并宣布决定之前，应当审查双方陈述。</p><p>should be examined 为建议性被动，before 后 is announced 描述流程中的另一步。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The statements should examined 缺 be；should be examined 仍不表示审查已经完成。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对照朗读 should be heard 和 was heard，听辨建议与事实；强调 without interruption，以表达程序要求。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Every complaint should be heard without interruption. The chair recorded each resident&#39;s main concern. A written explanation was sent after the meeting.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句虚构社区争议处理流程，包含一项原则和两项具体步骤。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句说明原则，后二句报告实际动作，建议与事实清楚分开。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句能证明双方陈述已经审查吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> should 表示应当采取的措施。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The records must be ___.（kept/keep）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> kept</p><p><strong>解析：</strong> 被动结构需要过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“决定已经公布”写成现在完成时被动。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The decision has been announced.</p><p><strong>解析：</strong> has been 加过去分词报告完成事实。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词的被动结构。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-036">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
